export interface SeedCategory {
  id: string;
  name: string;
  slug: string;
  icon: string;
  description: string;
  imageUrl: string;
  displayOrder: number;
}

export interface SeedBrand {
  id: string;
  categoryId: string;
  name: string;
  slug: string;
  logoUrl: string;
  isPopular: boolean;
  displayOrder: number;
}

export interface SeedModel {
  id: string;
  brandId: string;
  categoryId: string;
  name: string;
  slug: string;
  series: string;
  imageUrl: string;
  releaseYear: number;
  basePrice: number;
  minPrice: number;
  maxPrice: number;
  isPopular: boolean;
  isFeatured: boolean;
  specifications: Record<string, any>;
  variants: {
    id: string;
    name: string;
    slug: string;
    ram?: string;
    storage?: string;
    processor?: string;
    gpu?: string;
    screenSize?: string;
    color?: string;
    basePrice: number;
    minPrice: number;
    maxPrice: number;
    isDefault?: boolean;
  }[];
}

export interface SeedQuestion {
  id: string;
  categoryId?: string;
  brandId?: string;
  modelId?: string;
  title: string;
  subtitle: string;
  code: string;
  questionType: 'SINGLE_CHOICE' | 'MULTI_CHOICE' | 'YES_NO' | 'DROPDOWN';
  displayOrder: number;
  answers: {
    id: string;
    code: string;
    label: string;
    description?: string;
    icon?: string;
    adjustmentType: 'FIXED' | 'PERCENTAGE';
    adjustmentValue: number;
    isRejection?: boolean;
    warningMessage?: string;
    displayOrder: number;
  }[];
}

